                    if (!mine.length) return null;
                    const api = (typeof getApiConfig === 'function') ? getApiConfig(true) : null;
                    if (!api || !api.key) return null;
                    const ask = `你身上有这些东西：
${mine.map((i, n) => `${n + 1}. ${i.name}${i.desc ? '（' + i.desc + '）' : ''}`).join('\n')}
这会儿你想对其中某一样做点什么——送给${uname(char)}、用掉、或者不小心弄丢了。
